import { openPolicy, type Policy, processClaim } from "./policy.js";
import { quotePremium } from "./premium.js";

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface ScenarioOutput {
  results: object[];
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  let previousContracts = 0;
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, index) => {
    if (step.op === "claim") return processClaim(policies.get(step.policy)!, step.incident.damages);
    const premium = quotePremium(step.items, scenario.customer, previousContracts);
    previousContracts += 1;
    policies.set(index, openPolicy(step.items));
    return { premium };
  });
  return { results };
}
import type { Damage, Item } from "./claimOffice.js";
import * as priceList from "./priceList.js";
import { damagePayout } from "./reimbursement.js";
import { ScenarioRejection } from "./rejection.js";
import { roundPayoutInMHPCOsFavor } from "./rounding.js";

const CAP_MULTIPLIER = 2;

export interface Policy {
  items: Item[];
  remainingCap: number;
}

function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + priceList.insuranceValue(item.type), 0);
}

function payoutCap(items: Item[]): number {
  return CAP_MULTIPLIER * insuranceSum(items);
}

export function openPolicy(items: Item[]): Policy {
  return { items, remainingCap: payoutCap(items) };
}

export class UninsuredItemError extends ScenarioRejection {
  constructor(type: string) {
    super(`Damaged item type "${type}" is not covered by the policy`);
  }
}

function insuredItemFor(policy: Policy, damage: Damage): Item {
  const insured = policy.items.find((item) => item.type === damage.itemType);
  if (insured === undefined) throw new UninsuredItemError(damage.itemType);
  return insured;
}

function claimPayout(policy: Policy, damages: Damage[]): number {
  return damages.reduce(
    (sum, damage) => sum + damagePayout(insuredItemFor(policy, damage), damage.amount),
    0,
  );
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

function drawFromRemainingCap(policy: Policy, desiredPayout: number): number {
  const payout = Math.min(policy.remainingCap, desiredPayout);
  policy.remainingCap -= payout;
  return payout;
}

export function processClaim(policy: Policy, damages: Damage[]): ClaimResult {
  const desiredPayout = roundPayoutInMHPCOsFavor(claimPayout(policy, damages));
  const payout = drawFromRemainingCap(policy, desiredPayout);
  return { payout, remainingCap: policy.remainingCap };
}
